engine.getRank:
function getRank(trophyCount) {
  var n = Number(trophyCount) || 0;
  if (n >= 100) return "Grandmaster";
  if (n >= 80)  return "Executive";
  if (n >= 60)  return "Architect";
  if (n >= 40)  return "Strategist";
  if (n >= 20)  return "Specialist";
  return "Novice";
}

// Returns { rank, currentIdx, nextRank, nextIdx, isMax,
//           currentThreshold, nextThreshold, trophiesNeeded,
//           progressToNext }. FROM v2 showTrophyGallery line 13-36.

engine.computeRankProgress:
function computeRankProgress(trophyCount) {
  var n = Number(trophyCount) || 0;
  var rankThresholds = [
    { name: "Novice",      min: 0 },
    { name: "Specialist",  min: 20 },
    { name: "Strategist",  min: 40 },
    { name: "Architect",   min: 60 },
    { name: "Executive",   min: 80 },
    { name: "Grandmaster", min: 100 },
  ];
  var currentIdx = 0;
  for (var i = rankThresholds.length - 1; i >= 0; i--) {
    if (n >= rankThresholds[i].min) { currentIdx = i; break; }
  }
  var isMax = currentIdx === rankThresholds.length - 1;
  var nextIdx = Math.min(currentIdx + 1, rankThresholds.length - 1);
  var currentThreshold = rankThresholds[currentIdx].min;
  var nextThreshold = rankThresholds[nextIdx].min;
  var trophiesNeeded = isMax ? 0 : nextThreshold - n;
  var progressToNext = isMax ? 100 :
    Math.min(100, Math.round(((n - currentThreshold) / (nextThreshold - currentThreshold)) * 100));
  return {
    rank: rankThresholds[currentIdx].name,
    currentIdx: currentIdx,
    nextRank: rankThresholds[nextIdx].name,
    nextIdx: nextIdx,
    isMax: isMax,
    currentThreshold: currentThreshold,
    nextThreshold: nextThreshold,
    trophiesNeeded: trophiesNeeded,
    progressToNext: progressToNext,
    rankThresholds: rankThresholds,
  };
}

// FROM v2 showTrophyGallery line 140-162. Trophies 0-69 always visible;
// 70+ unlock by rank tier.

engine.isTrophyVisible:
function isTrophyVisible(idx, rank) {
  var r = String(rank || "").toLowerCase();
  if (idx < 70) return true;
  if (idx >= 70 && idx <= 74) {
    return r === "specialist" || r === "strategist" || r === "architect" || r === "executive" || r === "grandmaster";
  }
  if (idx >= 75 && idx <= 79) {
    return r === "strategist" || r === "architect" || r === "executive" || r === "grandmaster";
  }
  if (idx >= 80 && idx <= 84) {
    return r === "architect" || r === "executive" || r === "grandmaster";
  }
  if (idx >= 85 && idx <= 94) {
    return r === "executive" || r === "grandmaster";
  }
  if (idx >= 95 && idx <= 103) return r === "grandmaster";
  return false;
}

// FROM v2 line 163-170. Which rank unlocks a trophy at this index?

engine.getRequiredRank:
function getRequiredRank(idx) {
  if (idx >= 70 && idx <= 74) return "Specialist";
  if (idx >= 75 && idx <= 79) return "Strategist";
  if (idx >= 80 && idx <= 84) return "Architect";
  if (idx >= 85 && idx <= 94) return "Executive";
  if (idx >= 95) return "Grandmaster";
  return "Specialist";
}

// Read user stats (v2-compat localStorage key). Returns the parsed
// blob or {unlockedTrophies:[]} as a safe default.

engine.readUserStats:
function readUserStats() {
  try {
    var raw = window.eli && window.eli.compat
      ? window.eli.compat.lsGet("eli_user_stats")
      : (typeof localStorage !== "undefined" ? localStorage.getItem("eli_user_stats") : null);
    if (!raw) return { unlockedTrophies: [] };
    var parsed = JSON.parse(raw);
    if (!parsed.unlockedTrophies) parsed.unlockedTrophies = [];
    return parsed;
  } catch (e) {
    return { unlockedTrophies: [] };
  }
}

// Engine entry — shapes everything view.js needs.
// Self-contained: kernel's evalBundle wraps each engine fn in
// `new Function(...)` so sibling references (readUserStats,
// computeRankProgress) throw "not defined" at call time. Both inlined.

engine.analyze:
function analyze(input, providers) {
  // Inline: readUserStats
  var stats = { unlockedTrophies: [] };
  try {
    var raw = window.eli && window.eli.compat
      ? window.eli.compat.lsGet("eli_user_stats")
      : (typeof localStorage !== "undefined" ? localStorage.getItem("eli_user_stats") : null);
    if (raw) {
      var parsed = JSON.parse(raw);
      if (parsed && typeof parsed === "object") {
        stats = parsed;
        if (!stats.unlockedTrophies) stats.unlockedTrophies = [];
      }
    }
  } catch (e) { /* defaults already set */ }
  var unlocked = stats.unlockedTrophies || [];
  // Inline: computeRankProgress
  var n = unlocked.length;
  var rankThresholds = [
    { name: "Novice",      min: 0 },
    { name: "Specialist",  min: 20 },
    { name: "Strategist",  min: 40 },
    { name: "Architect",   min: 60 },
    { name: "Executive",   min: 80 },
    { name: "Grandmaster", min: 100 },
  ];
  var currentIdx = 0;
  for (var i = rankThresholds.length - 1; i >= 0; i--) {
    if (n >= rankThresholds[i].min) { currentIdx = i; break; }
  }
  var isMax = currentIdx === rankThresholds.length - 1;
  var nextIdx = Math.min(currentIdx + 1, rankThresholds.length - 1);
  var currentThreshold = rankThresholds[currentIdx].min;
  var nextThreshold = rankThresholds[nextIdx].min;
  var trophiesNeeded = isMax ? 0 : nextThreshold - n;
  var progressToNext = isMax ? 100 :
    Math.min(100, Math.round(((n - currentThreshold) / (nextThreshold - currentThreshold)) * 100));
  var progress = {
    rank: rankThresholds[currentIdx].name,
    currentIdx: currentIdx,
    nextRank: rankThresholds[nextIdx].name,
    nextIdx: nextIdx,
    isMax: isMax,
    currentThreshold: currentThreshold,
    nextThreshold: nextThreshold,
    trophiesNeeded: trophiesNeeded,
    progressToNext: progressToNext,
    rankThresholds: rankThresholds,
  };
  return Promise.resolve({
    unlocked: unlocked,
    rank: progress.rank,
    progress: progress,
    raw: stats,
    overview: unlocked.length + " trophy" + (unlocked.length === 1 ? "" : "ies") +
      " · " + progress.rank,
    provenance: {
      kernelVersion: (window.eli && window.eli.kernelVersion) || "v3",
      toolVersion: "v3.0",
      docHash: null,
      timestamp: Date.now(),
    },
  });
}

