view.renderTrophyUnlockedToast:
function renderTrophyUnlockedToast(trophy) {
  // Self-contained — see renderSidebarBox comment. Both `_escTrophy`
  // and `_playNextTrophy` (which recurses via the toast-end setTimeout)
  // are inner functions so they share scope under one `new Function()`
  // wrapper instead of becoming separate isolated wrappers that can't
  // see each other.
  function _escTrophy(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _playNextTrophy() {
    if (!window._trophyQueue || window._trophyQueue.length === 0) {
      window._trophyIsShowing = false;
      return;
    }
    window._trophyIsShowing = true;
    var tNext = window._trophyQueue.shift();
    var colors = ["#febb02", "#f15025", "#4285f4", "#0f9d58", "#9c27b0", "#00bcd4"];
    var confettiHost = document.createElement("div");
    confettiHost.className = "_eli3_trophy_confetti";
    document.body.appendChild(confettiHost);
    for (var i = 0; i < 50; i++) {
      var conf = document.createElement("div");
      conf.className = "_eli3_trophy_confetti_piece";
      conf.style.width = (Math.random() * 8 + 4) + "px";
      conf.style.height = (Math.random() * 8 + 4) + "px";
      conf.style.backgroundColor = colors[Math.floor(Math.random() * colors.length)];
      conf.style.left = (Math.random() * 100) + "%";
      conf.style.top = "-10px";
      conf.style.opacity = String(Math.random() + 0.5);
      conf.style.transform = "rotate(" + (Math.random() * 360) + "deg)";
      confettiHost.appendChild(conf);
      void conf.offsetWidth;
      conf.style.top = (100 + Math.random() * 20) + "%";
      conf.style.transform = "rotate(" + (Math.random() * 720 - 360) + "deg)";
      conf.style.opacity = "0";
    }
    setTimeout(function () {
      if (confettiHost.parentNode) confettiHost.parentNode.removeChild(confettiHost);
    }, 3000);
    var toast = document.createElement("div");
    toast.className = "_eli3_trophy_unlock_toast";
    toast.innerHTML =
      '<div class="_eli3_trophy_unlock_icon">' + _escTrophy(tNext.icon || "🏆") + '</div>' +
      '<div class="_eli3_trophy_unlock_body">' +
        '<div class="_eli3_trophy_unlock_eyebrow">Achievement Unlocked</div>' +
        '<div class="_eli3_trophy_unlock_title">' + _escTrophy(tNext.title || tNext.id || "Trophy") + '</div>' +
        '<div class="_eli3_trophy_unlock_desc">' + _escTrophy(tNext.desc || "") + '</div>' +
      '</div>';
    document.body.appendChild(toast);
    setTimeout(function () { toast.classList.add("_eli3_trophy_unlock_in"); }, 50);
    setTimeout(function () {
      toast.classList.remove("_eli3_trophy_unlock_in");
      toast.classList.add("_eli3_trophy_unlock_out");
      setTimeout(function () {
        if (toast.parentNode) toast.parentNode.removeChild(toast);
        _playNextTrophy();
      }, 600);
    }, 4500);
  }
  // Main body — enqueue + start playback if idle.
  if (!trophy || typeof document === "undefined") return;
  if (typeof window._trophyQueue === "undefined") {
    window._trophyQueue = [];
    window._trophyIsShowing = false;
    window._trophyShownIds = {};
  }
  var tid = trophy.id;
  if (tid && window._trophyShownIds[tid]) return;
  if (tid) window._trophyShownIds[tid] = true;
  window._trophyQueue.push(trophy);
  if (!window._trophyIsShowing) _playNextTrophy();
}

jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };
  var bundle = eli.tools._loaded["trophy_gallery"];
  if (!bundle) return;
  var efns = bundle._eliEngineFns || {};
  var vfns = bundle._eliViewFns || {};
  var computeRankProgress = efns.computeRankProgress;
  var renderSidebarBox    = vfns.renderSidebarBox;
  var renderGallery       = vfns.renderGallery;
  var renderTrophyDetails        = vfns.renderTrophyDetails;
  var renderTrophyUnlockedToast  = vfns.renderTrophyUnlockedToast;
  if (!computeRankProgress || !renderSidebarBox || !renderGallery) {
    eli.log.event("tool", "trophy_gallery_load_failed", {
      hasProgress: !!computeRankProgress, hasSidebar: !!renderSidebarBox, hasGallery: !!renderGallery,
    });
    return;
  }

  // ─── Stats source ───────────────────────────────────────────────
  // v2 wrote stats (including unlockedTrophies + unlockedDates) to IDB
  // store "stats" with stat_id="eli_user_stats". Reads from there first;
  // falls back to localStorage compat key only if IDB miss.
  var _userStats = null;
  var _statsLoaded = false;
  function _loadUserStats() {
    if (_statsLoaded) return Promise.resolve(_userStats);
    if (!eli.storage || typeof eli.storage.get !== "function") {
      _statsLoaded = true;
      return Promise.resolve(null);
    }
    return eli.storage.get("stats", "eli_user_stats").then(function (row) {
      if (row && typeof row === "object") {
        _userStats = row;
        if (!_userStats.unlockedTrophies) _userStats.unlockedTrophies = [];
      } else {
        try {
          var raw = eli.compat ? eli.compat.lsGet("eli_user_stats") : null;
          if (raw) {
            _userStats = JSON.parse(raw);
            if (!_userStats.unlockedTrophies) _userStats.unlockedTrophies = [];
          }
        } catch (e) { /* tolerate */ }
      }
      _statsLoaded = true;
      return _userStats;
    }).catch(function () {
      _statsLoaded = true;
      return null;
    });
  }
  _loadUserStats();

  // ─── Trophy catalog read ─────────────────────────────────────────
  // Trophies live in IDB store "trophies" (kernel STORE_TROPHIES). The
  // data bundle (__data_trophies) populates this on auto-sync.
  function _readTrophies() {
    if (!eli.storage || typeof eli.storage.getAll !== "function") return Promise.resolve([]);
    return eli.storage.getAll("trophies").then(function (rows) {
      // Filter out metadata rows (ids starting with _).
      return (rows || []).filter(function (r) {
        return r && r.id && String(r.id).charAt(0) !== "_";
      });
    }).catch(function () { return []; });
  }

  // ─── Sidebar slot ────────────────────────────────────────────────
  function _build(opts) {
    var unlocked = (_userStats && _userStats.unlockedTrophies) || [];
    var progress = computeRankProgress(unlocked.length);
    renderSidebarBox({
      mount: opts.mount,
      count: unlocked.length,
      rank: progress.rank,
      onClick: function () { _openGallery(); },
    });
    // If IDB read still pending, queue a sidebar repaint when it lands.
    if (!_statsLoaded) {
      _loadUserStats().then(function () {
        try { if (eli.dashboard && eli.dashboard.refreshSidebar) eli.dashboard.refreshSidebar(); }
        catch (e) { /* tolerate */ }
      });
    }
  }

  if (eli.dashboard && typeof eli.dashboard.registerSidebarSlot === "function") {
    // order: 90 — pin to the bottom of the sidebar (above the
    // collapse-chevron). eli_stats sits at default order 50, so the
    // trophy chip lands below it. Bigger order = further down.
    eli.dashboard.registerSidebarSlot("trophy_gallery", _build, { order: 90 });
  }

  // ─── Open the gallery overlay ────────────────────────────────────
  function _openGallery() {
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedTrophyGallery"); } catch (e) {}
    try {
      var cur = eli.fsm.getCurrent ? eli.fsm.getCurrent() : null;
      if (cur === "idle") eli.fsm.transition("scanning");
    } catch (e) {}
    // Read stats from IDB cache + trophy catalog in parallel. computeRankProgress
    // is a pure engine fn — safe to call directly on the resolved stats.
    Promise.all([
      _loadUserStats(),
      _readTrophies(),
    ]).then(function (r) {
      var stats = r[0] || { unlockedTrophies: [] };
      var trophies = r[1] || [];
      var unlocked = stats.unlockedTrophies || [];
      var progress = computeRankProgress(unlocked.length);
      var ui = renderGallery({
        unlocked: unlocked,
        rank: progress.rank,
        progress: progress,
        trophies: trophies,
        onDetails: function (trophyId) {
          var def = trophies.filter(function (t) { return t.id === trophyId; })[0];
          if (!def || !renderTrophyDetails) return;
          var isUnlocked = unlocked.indexOf(trophyId) !== -1;
          var unlockedAt = stats.unlockedDates && stats.unlockedDates[trophyId];
          // Pass full stats so the locked-trophy progress bar can read
          // `stats[trophy.metric]` or call `trophy.getProgress(stats)`.
          renderTrophyDetails({
            trophy: def,
            unlocked: isUnlocked,
            unlockedAt: unlockedAt,
            stats: stats,
          });
        },
        onClose: function () {
          try { eli.fsm.transition("idle"); } catch (e) {}
        },
        onReset: _confirmReset,
      });
      // Stash so external code can close (e.g. tile_settings dispatch).
      eli._trophyGalleryUi = ui;
    }).catch(function (err) {
      eli.log.event("tool", "trophy_gallery_open_failed", { msg: err && err.message });
      if (typeof showToast === "function") {
        showToast("Trophy gallery failed: " + (err && err.message || "unknown"), "err");
      }
    });
  }

  // ─── Reset confirmation ──────────────────────────────────────────
  // Admin-gated wipe of all stats + trophies. Mirrors v2 reset flow at
  // showTrophyGallery line 238. Requires password if eli.admin exposes
  // a password gate; otherwise plain confirm dialog.
  function _confirmReset() {
    if (typeof showEliDialog !== "function") return;
    var ov = showEliDialog({
      variant: "danger",
      tier: "premium",
      icon: "⚠️",
      title: "Reset Trophies",
      body: 'This will <strong style="color:#ef4444;">permanently erase</strong> ALL trophies, stats, streaks, and rank progress. You cannot undo this.',
      primary: {
        label: "Wipe Data",
        onclick: function () {
          // Best-effort wipe across the three storage locations.
          try { if (eli.compat) eli.compat.lsRemove("eli_user_stats"); } catch (e) {}
          try { if (eli.storage) eli.storage.clearStore("stats").catch(function () {}); } catch (e) {}
          try { if (eli.storage) eli.storage.clearStore("trophies").catch(function () {}); } catch (e) {}
          if (typeof showToast === "function") showToast("Trophies & stats reset.", "ok");
          if (eli._trophyGalleryUi && eli._trophyGalleryUi.close) {
            try { eli._trophyGalleryUi.close(); } catch (e) {}
          }
          // Refresh sidebar so the empty state lands immediately.
          try { if (eli.dashboard && eli.dashboard.refresh) eli.dashboard.refresh(); } catch (e) {}
        },
      },
      secondary: { label: "Cancel" },
    });
    return ov;
  }

  // ─── Channels ────────────────────────────────────────────────────
  // Tools that trigger an unlock (Build Draft completion, Error Review
  // scan, etc.) fire the celebration via:
  //   eli.dispatch("trophies", "unlocked", trophy)
  // The handler shows confetti + animated toast. Dedups by trophy.id
  // so the same unlock can't double-pop within a session.
  eli.register({
    tile: { app_trophy_gallery: function () { _openGallery(); } },
    trophies: {
      unlocked: function (trophy) {
        if (!renderTrophyUnlockedToast) return;
        try { renderTrophyUnlockedToast(trophy); }
        catch (e) { eli.log.event("tool", "trophy_unlock_toast_failed", { msg: e && e.message }); }
        // Invalidate the cached stats so the sidebar chip + gallery
        // both pick up the new trophy on next read.
        _statsLoaded = false;
        _userStats = null;
        _loadUserStats().then(function () {
          try { if (eli.dashboard && eli.dashboard.refreshSidebar) eli.dashboard.refreshSidebar(); }
          catch (e) {}
        });
      },
    },
  });

  // Back-compat global so v2-shim consumers still calling
  // window.showTrophyUnlocked(trophy) keep working. Removable once
  // every caller has migrated to eli.dispatch.
  window.showTrophyUnlocked = function (trophy) {
    eli.dispatch("trophies", "unlocked", trophy);
  };

  eli.log.event("tool", "trophy_gallery_initialized", {});
}

jsonTools.css:
/* trophy_gallery tool styles — sidebar chip + full gallery overlay.
   Injected as <style data-tool="trophy_gallery">. */

/* Push the trophy slot to the BOTTOM of the sidebar column. The slot
   host is flex-column (kernel CSS); margin-top: auto on the wrapper
   shoves it to the bottom regardless of how many other slots register.
   Targeting the slot wrapper specifically (data-slot-id) rather than
   ._eli3_sidebar_trophy so the same chip works if mounted elsewhere
   (e.g. a future Settings panel). */
._eli3_sidebar_slot[data-slot-id="trophy_gallery"] {
  margin-top: auto;
}

/* Sidebar trophy box — v2-style (taskpane.css :2428 .v1-trophy).
   Stacked: icon, rank, count. Matches the visual weight of the
   User Stats boxes above it. */
._eli3_sidebar_trophy {
  background: #1c2541;
  border: 1px solid #3a506b;
  padding: 8px 4px 10px;
  text-align: center;
  cursor: pointer;
  transition: transform 0.1s, background 0.15s, border-color 0.15s;
}
._eli3_sidebar_trophy:hover {
  transform: scale(1.02);
  background: #1e2a4a;
  border-color: #4a6188;
}
._eli3_sidebar_trophy_icon {
  display: block;
  font-size: 16px;
  margin-bottom: 2px;
}
._eli3_sidebar_trophy_rank {
  font: 900 11px/1 'Inter', sans-serif;
  color: #ffffff;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
._eli3_sidebar_trophy_count {
  margin-top: 2px;
  font: 800 11px/1 'Inter', sans-serif;
  color: #e5cc80;
  letter-spacing: 0.3px;
}
body.light-mode ._eli3_sidebar_trophy {
  background: #ffffff;
