  border: 1px solid rgba(255,255,255,0.1);
  box-shadow: 0 20px 40px rgba(0,0,0,0.6);
  width: 300px;
  padding: 32px 24px;
  text-align: center;
  position: relative;
  transform: scale(0.92);
  transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}
._eli3_trophy_details_open ._eli3_trophy_details_box { transform: scale(1); }
._eli3_trophy_details_box_unlocked {
  background: linear-gradient(145deg, #1e293b 0%, #0f172a 100%);
  border: 1px solid rgba(251, 191, 36, 0.30);
}
._eli3_trophy_details_close {
  position: absolute;
  top: 8px; right: 12px;
  background: transparent;
  border: 0;
  color: #94a3b8;
  font: 400 22px/1 'Inter', sans-serif;
  cursor: pointer;
  padding: 4px 8px;
  transition: color 0.15s;
}
._eli3_trophy_details_close:hover { color: #fff; }

._eli3_trophy_details_eyebrow {
  font: 800 10px/1 'Inter', sans-serif;
  color: #64748b;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 16px;
}
._eli3_trophy_details_eyebrow_gold {
  color: #fbbf24;
  text-shadow: 0 0 10px rgba(251, 191, 36, 0.5);
}
._eli3_trophy_details_icon {
  font-size: 72px;
  line-height: 1;
  margin-bottom: 16px;
}
._eli3_trophy_details_icon_gold {
  filter: drop-shadow(0 10px 20px rgba(251, 191, 36, 0.4));
  animation: _eli3_trophy_icon_pulse 2s infinite;
}
@keyframes _eli3_trophy_icon_pulse {
  0%, 100% { transform: scale(1); }
  50%      { transform: scale(1.06); }
}
._eli3_trophy_details_icon_locked {
  filter: grayscale(100%) opacity(0.3);
}
._eli3_trophy_details_title {
  font: 900 24px/1.1 'Inter', sans-serif;
  color: #fff;
  margin-bottom: 8px;
}
._eli3_trophy_details_title_locked { color: #94a3b8; font-size: 20px; }
._eli3_trophy_details_date {
  font: 800 10px/1 'Inter', sans-serif;
  color: #34d399;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 12px;
}
._eli3_trophy_details_desc {
  font: 500 13px/1.5 'Inter', sans-serif;
  color: #cbd5e1;
  margin-bottom: 24px;
}
._eli3_trophy_details_box ._eli3_trophy_details_desc:last-child { margin-bottom: 0; }
._eli3_trophy_details_share {
  background: rgba(251, 191, 36, 0.15);
  border: 1px solid rgba(251, 191, 36, 0.5);
  color: #fbbf24;
  padding: 12px 24px;
  font: 800 14px/1 'Inter', sans-serif;
  cursor: pointer;
  width: 100%;
  transition: background 0.2s;
}
._eli3_trophy_details_share:hover { background: rgba(251, 191, 36, 0.25); }

._eli3_trophy_details_progress {
  margin-top: 24px;
  width: 100%;
  text-align: left;
}
._eli3_trophy_details_progress_head {
  display: flex;
  justify-content: space-between;
  font: 800 11px/1 'Inter', sans-serif;
  color: #94a3b8;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 8px;
}
._eli3_trophy_details_progress_score { color: #fff; }
._eli3_trophy_details_progress_track {
  width: 100%;
  height: 8px;
  background: rgba(255,255,255,0.05);
  overflow: hidden;
  border: 1px solid rgba(255,255,255,0.1);
}
._eli3_trophy_details_progress_fill {
  height: 100%;
  background: linear-gradient(90deg, #3b82f6, #60a5fa);
  box-shadow: 0 0 10px rgba(59, 130, 246, 0.5);
  transition: width 0.5s ease;
}
._eli3_trophy_details_hint {
  margin-top: 24px;
  font: 600 12px/1.4 'Inter', sans-serif;
  color: #64748b;
  font-style: italic;
}

/* ─── Trophy-unlock celebration (port of v2 _trophyQueue.js) ─────── */
._eli3_trophy_confetti {
  position: fixed;
  top: 0; left: 0;
  width: 100%; height: 100%;
  pointer-events: none;
  z-index: 9998;
  overflow: hidden;
}
._eli3_trophy_confetti_piece {
  position: absolute;
  transition: transform 3s linear, top 3s ease-in, opacity 3s ease-out;
}
._eli3_trophy_unlock_toast {
  position: fixed;
  top: -100px;
  left: 50%;
  transform: translateX(-50%);
  background: linear-gradient(135deg, #1e293b 0%, #0f172a 100%);
  color: #fff;
  padding: 16px 20px;
  border-radius: 20px;
  box-shadow: 0 10px 30px rgba(0,0,0,0.3), 0 0 0 1px rgba(255,255,255,0.1);
  display: flex;
  align-items: center;
  gap: 14px;
  z-index: 9999;
  transition: top 0.6s cubic-bezier(0.34, 1.56, 0.64, 1), opacity 0.6s;
  max-width: 360px;
}
._eli3_trophy_unlock_in { top: 30px; }
._eli3_trophy_unlock_out { top: -100px; opacity: 0; }
._eli3_trophy_unlock_icon {
  font-size: 32px;
  filter: drop-shadow(0 2px 4px rgba(0,0,0,0.2));
}
._eli3_trophy_unlock_body { min-width: 0; }
._eli3_trophy_unlock_eyebrow {
  font: 800 9px/1 'Inter', sans-serif;
  color: #38bdf8;
  text-transform: uppercase;
  letter-spacing: 0.8px;
}
._eli3_trophy_unlock_title {
  font: 700 15px/1.2 'Inter', sans-serif;
  color: #f8fafc;
  margin-top: 4px;
}
._eli3_trophy_unlock_desc {
  font: 500 11px/1.3 'Inter', sans-serif;
  color: #94a3b8;
  margin-top: 2px;
}
